		if ( strpos( $t, 'payout_claims' ) !== false ) { foreach ( $this->claims as $r ) if ( (int) $r['referral_id'] === (int) $d['referral_id'] ) return false; $d['id'] = ++$this->insert_id; $this->claims[] = $d; return 1; }
		$this->audit[] = $d; return 1;
