		if ( strpos( $q, 'idempotency' ) !== false ) { preg_match( '/mutation_identity_hash = (\S+)/', $q, $m ); foreach ( $this->idempotency as $r ) if ( $r['mutation_identity_hash'] === trim( $m[1] ?? '', "'\"" ) ) return $r; if ( preg_match( '/WHERE id = (\d+)/', $q, $m ) ) foreach ( $this->idempotency as $r ) if ( (int) $r['id'] === (int) $m[1] ) return $r; }
