		if ( strpos( $q, 'payout_claims' ) !== false ) { preg_match( '/referral_id = (\d+)/', $q, $m ); foreach ( $this->claims as $r ) if ( (int) $r['referral_id'] === (int) ( $m[1] ?? 0 ) ) return $r; }
