			if ( preg_match( "/lease_expires_at = '([^']+)'/", $q, $m ) ) $r['lease_expires_at'] = $m[1]; elseif ( strpos( $q, 'lease_expires_at = NULL' ) !== false ) $r['lease_expires_at'] = null;
